            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                pal[l][r] = s.charAt(l) == s.charAt(r) &&
                            (len <= 2 || pal[l + 1][r - 1]);
            }
        }

        int[] dp = new int[n];

        for (int i = 0; i < n; i++) {
            if (pal[0][i]) {
                dp[i] = 0;
            } else {
                dp[i] = i;
                for (int j = 1; j <= i; j++) {
                    if (pal[j][i]) {
                        dp[i] = Math.min(dp[i], dp[j - 1] + 1);
                    }
                }
            }
        }

        return dp[n - 1];
    }
}

