def dag_shortest_path(n, edges, source):
    graph = [[] for _ in range(n)]
    indegree = [0] * n

    for u, v, w in edges:
        graph[u].append((v, w))
        indegree[v] += 1

    queue = deque(i for i in range(n) if indegree[i] == 0)
    order = []

    while queue:
        u = queue.popleft()
        order.append(u)
        for v, _ in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    INF = float('inf')
    dp = [INF] * n
    dp[source] = 0

    for u in order:
        if dp[u] == INF:
            continue
        for v, w in graph[u]:
            dp[v] = min(dp[v], dp[u] + w)

    return dp

