        if (pos == s.length()) return sum == target ? 1 : 0;

        if (seen[pos][sum][tight]) return memo[pos][sum][tight];
        seen[pos][sum][tight] = true;

        int limit = tight == 1 ? s.charAt(pos) - '0' : 9;
        long answer = 0;

