def reroot_tree(n, graph):
    subtree = [1] * n
    answer = [0] * n

    def dfs1(u, parent):
        for v in graph[u]:
            if v == parent:
                continue
            dfs1(v, u)
            subtree[u] += subtree[v]
            answer[0] += subtree[v]

    def dfs2(u, parent):
        for v in graph[u]:
            if v == parent:
                continue

            answer[v] = answer[u] + n - 2 * subtree[v]
            dfs2(v, u)

    dfs1(0, -1)
    dfs2(0, -1)

    return answer

