def lcs_space_optimized(a, b):
    if len(b) > len(a):
        a, b = b, a

    prev = [0] * (len(b) + 1)

    for x in a:
        curr = [0] * (len(b) + 1)

        for j, y in enumerate(b, 1):
            if x == y:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])

        prev = curr

    return prev[-1]

